html:
{%- import "costeo_yelke/templates/print/oc_yelke.html" as oc -%}
{#- Factura de compra (registro de la factura del proveedor). Diseño: templates/print/oc_yelke.html -#}
{{ oc.estilos() }}
{{ oc.membrete_encabezado(doc, no_letterhead, print_settings, "Factura de compra") }}
<div class="pdf-container">
{{ oc.marca_borrador(doc) }}
{{ oc.datos(doc, {"etiqueta": "Proveedor", "nombre": doc.supplier_name or doc.supplier, "rfc": rfc_tercero("Supplier", doc.supplier), "direccion": direccion_lineas(doc.supplier_address)},
    [("Fecha de registro", fecha_corta(doc.posting_date)),
     ("Factura del proveedor", doc.get("bill_no")),
     ("Fecha de la factura", fecha_corta(doc.bill_date) if doc.get("bill_date") else None),
     ("Orden de compra", (doc.items[0].purchase_order if doc.items else None)),
     ("Recibo", (doc.items[0].purchase_receipt if doc.items else None)),
     ("Vence", fecha_corta(doc.due_date) if doc.due_date else None),
     ("Moneda", doc.currency)]) }}
{{ oc.tabla_articulos(doc, mostrar_descuento=true) }}
{{ oc.cierre(doc) }}
</div>
{{ oc.membrete_pie(doc, no_letterhead, print_settings) }}
